def transform(grid):
    from collections import Counter
    R, C = len(grid), len(grid[0])
    div_rows = {r for r in range(R) if len(set(grid[r])) == 1}
    div_cols = {c for c in range(C) if len({grid[r][c] for r in range(R)}) == 1}
    divcolor = next(iter({grid[r][c] for r in div_rows for c in (0,)})) if div_rows else None

    bands, start = [], None
    for r in range(R):
        if r in div_rows:
            if start is not None: bands.append((start, r - 1)); start = None
        elif start is None:
            start = r
    if start is not None: bands.append((start, R - 1))

    colbands, start = [], None
    for c in range(C):
        if c in div_cols:
            if start is not None: colbands.append((start, c - 1)); start = None
        elif start is None:
            start = c
    if start is not None: colbands.append((start, C - 1))

    cnt = Counter(grid[r][c] for r in range(R) for c in range(C)
                  if r not in div_rows and c not in div_cols)
    majority = cnt.most_common(1)[0][0]

    out = []
    for r0, r1 in bands:
        row = []
        for c0, c1 in colbands:
            n = sum(1 for r in range(r0, r1 + 1) for c in range(c0, c1 + 1)
                    if grid[r][c] != majority and grid[r][c] != divcolor)
            row.append(1 if n == 2 else majority)
        out.append(row)
    return out
